export async function runCaptureRepair({browser,serve,evidence,root}){
  const server=await serve(root),context=await browser.newContext(),page=await context.newPage();let details={cases:[]},carry;
  await page.route('**/synthetic-capture-repair',route=>route.fulfill({contentType:'text/html',body:'<!doctype html><title>SYNTHETIC inactive capture repair</title>'}));
  try{
    await page.goto(server.origin+'/synthetic-capture-repair');
    for(const phase of ['prepare','target','folder-ack','core-ack','duplicate','refusals','replay-target','replay-folder-ack','replay-core-ack','replay-duplicate']){
      if(phase!=='prepare')await page.reload();
      const result=await page.evaluate(repairPage,{phase,carry,expectStatusVulnerable:process.env.SCOREBRUSH_F0A_EXPECT_VULNERABLE==='1'});carry=result.carry??carry;details.cases.push(...result.cases);if(result.measurements)details.measurements=result.measurements;
    }
    for(const item of details.cases){assert(item.pass,item.name);console.log('capture-repair: '+item.name);}
    return {name:'capture-repair',assertions:details.cases.length,cases:details.cases.length,realIndexedDB:true,realOPFS:true};
  }catch(error){details.failure={name:error.name,message:error.message,stack:error.stack};const latest=await page.evaluate(()=>window.captureRepairCases??[]).catch(()=>[]);if(latest.length)details.interruptedCases=latest;throw error;}
  finally{await writeFile(resolve(evidence,'capture-repair.json'),JSON.stringify(details,null,2)+'\n');await writeFile(resolve(evidence,'capture-repair.txt'),[...details.cases.map(item=>(item.pass?'PASS ':'FAIL ')+item.name),...(details.failure?['FAIL '+details.failure.message]:[])].join('\n')+'\n');await context.close();await server.close();}
}

